INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('meeting-rooms', 7, NULL, 'def gen():
    _s = [574577157]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    M = 1000000000
    L = 1000000
    N = 200000
    lines = []
    for _ in range(N):
        s = r(0, M - 1)
        e = min(M, s + r(1, L))
        lines.append(f"{s} {e}")
    return f"{N}\n" + "\n".join(lines) + "\n"
', '151', 0);
